using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEngine.UI;using Abyss;using Abyss.Story;
public static class VoyageSailingCheck {
 static Stack<IEnumerator> tasks;static string report;static double end;static int errors;static Keyboard keyboard;
 public static void Begin(){Directory.CreateDirectory("Tools/SailingUpdate");report="Sailing, audio, loot, shortcut and cinematic checks\nRuntime-only controlled inputs and actor positions.\n";errors=0;end=EditorApplication.timeSinceStartup+150;tasks=new();tasks.Push(Run());keyboard=InputSystem.AddDevice<Keyboard>("SailingCheckKeyboard");Application.logMessageReceived+=Log;EditorApplication.update+=Tick;EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Focus();}
 static void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception)errors++;}
 static void Tick(){Application.runInBackground=true;EditorApplication.QueuePlayerLoopUpdate();try{if(EditorApplication.timeSinceStartup>end)throw new Exception("Sailing check timeout");if(tasks.Count==0){Finish();return;}var i=tasks.Peek();if(!i.MoveNext()){tasks.Pop();return;}if(i.Current is IEnumerator child)tasks.Push(child);else if(i.Current is AsyncOperation op)tasks.Push(Op(op));}catch(Exception e){report+="FAIL "+e+"\n";Finish();}}
 static void Finish(){File.WriteAllText("Tools/SailingUpdate/check.txt",report);if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);EditorApplication.update-=Tick;Application.logMessageReceived-=Log;}
 static void Check(bool value,string text){report+=(value?"PASS ":"FAIL ")+text+"\n";File.WriteAllText("Tools/SailingUpdate/check.txt",report);if(!value)throw new Exception(text);}
 static IEnumerator Op(AsyncOperation op){while(!op.isDone)yield return null;}
 static IEnumerator Wait(float seconds){double t=EditorApplication.timeSinceStartup+seconds;while(EditorApplication.timeSinceStartup<t)yield return null;}
 static IEnumerator P(JourneyStage stage){InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.P));yield return Wait(.12f);InputSystem.QueueStateEvent(keyboard,new KeyboardState());double t=EditorApplication.timeSinceStartup+10;while((StorySceneJourney.Instance.Stage!=stage||StorySceneJourney.Instance.IsTransitioning)&&EditorApplication.timeSinceStartup<t)yield return null;yield return Wait(.35f);Check(StorySceneJourney.Instance.Stage==stage&&!StorySceneJourney.Instance.IsTransitioning,"Undisclosed P shortcut advances to "+stage);}
 static IEnumerator Talk(){double t=EditorApplication.timeSinceStartup+10;while(EditorApplication.timeSinceStartup<t){var d=UnityEngine.Object.FindFirstObjectByType<ShipVisitDialogue>();if(d&&d.ReadyForGameplay)yield break;if(d&&d.UI.Active)d.UI.Advance();yield return null;}throw new Exception("Talk timeout");}
 static void Warp(ShipController ship,Vector2 at){var delta=(Vector3)at-ship.transform.position;delta.z=0;ship.GetComponent<Rigidbody2D>().position=at;ship.transform.position=new Vector3(at.x,at.y,ship.transform.position.z);Unity.Cinemachine.CinemachineCore.OnTargetObjectWarped(ship.transform,delta);Camera.main.transform.position+=delta;Physics2D.SyncTransforms();}
 static IEnumerator Run(){
 StorySceneJourney.Instance.NewGame();yield return Wait(2.2f);var story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();story.ui.Clear();var pilot=story.player;var sound=UnityEngine.Object.FindFirstObjectByType<UnderwaterSceneAudio>();Check(sound.ambienceVolume>=.15f,"Underwater ambience gain is increased");Check(pilot.bodyHalfHeight>.4f,"Player fish grows proportionally with the underwater cast");pilot.ControlsLocked=false;var body=pilot.GetComponent<Rigidbody2D>();body.position=new Vector2(story.Discovery.x+15,pilot.surfaceY-1);pilot.transform.position=body.position;body.linearVelocity=Vector2.up*pilot.speed;pilot.testInput=Vector2.up;pilot.testSprint=true;bool airborne=false;float max=body.position.y,exitGain=0;double flight=EditorApplication.timeSinceStartup+4;while(EditorApplication.timeSinceStartup<flight){max=Mathf.Max(max,body.position.y);if(pilot.Airborne&&!airborne){airborne=true;exitGain=sound.LastSplashGain;}if(airborne&&!pilot.Airborne)break;yield return Wait(.02f);}Check(airborne&&max>pilot.surfaceY+1,"Surface boost produces the higher short jump; peak="+max);Check(sound.LastSplashGain>exitGain&&exitGain>0&&sound.GetComponentsInChildren<AudioSource>().Any(a=>a.clip&&a.clip.name=="blup"),"Exit blup is quiet and landing blup is louder");Check(UnityEngine.Object.FindObjectsByType<SurfaceSplash>(FindObjectsSortMode.None).Length>=40,"Landing emits the larger splash");pilot.testInput=Vector2.zero;pilot.testSprint=false;
 yield return P(JourneyStage.FirstShip);yield return Talk();yield return Wait(.15f);var ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();var ui=UnityEngine.Object.FindFirstObjectByType<ShipUIManager>();var water=ship.GetComponent<ShipWaterPurification>();Check(ship.energyDrainRate>0&&water.forwardDistanceForFull==420,"First visit consumes energy and uses shorter purification travel");Check(UnityEngine.Object.FindFirstObjectByType<VoyageMusic>().GetComponents<AudioSource>().Any(a=>a.isPlaying&&a.clip&&a.clip.name=="peaceful"),"Ossuary 7 plays in the non-combat ship visit");Check(GameObject.Find("Control instructions").GetComponent<Text>().text.Contains("Su arıtımı yapabilmek"),"First visit displays the requested swimming/purification hint");Check(!UnityEngine.Object.FindFirstObjectByType<EnemySpawner>().enabled&&UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None).Length==0,"First visit remains attack-free");var field=ship.GetComponent<PeacefulEnergyField>();var drops=UnityEngine.Object.FindObjectsByType<Loot>(FindObjectsSortMode.None);Check(drops.Length>=10&&drops.All(l=>l.energyOnly),"Random sea pickups are energy-only");var loot=drops.First();Check(loot.GetComponent<ShipLootVisual>().CurrentIcon==Resources.Load<Sprite>("Voyage/loot_energy")&&loot.GetComponentInChildren<SpriteRenderer>().bounds.size.magnitude>1.3f,"Energy pickup is a large visible lightning icon even in XP mode");ScreenCapture.CaptureScreenshot("Tools/SailingUpdate/peaceful-energy.png");yield return Wait(.15f);
 Time.timeScale=0;field.enabled=false;foreach(var other in drops)if(other&&other!=loot)UnityEngine.Object.Destroy(other.gameObject);yield return Wait(.15f);ship.currentEnergy=50;float xp=ui.currentXP;loot.transform.position=ship.transform.position;Time.timeScale=1;yield return Wait(.15f);Check(ship.currentEnergy==75&&ui.currentXP==xp,"Sea lightning refuels the ship in XP mode without granting XP");
 Warp(ship,new Vector2(30,0));InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.D));yield return Wait(.06f);Check(ship.TryDash(Vector2.up),"Native dash starts");yield return Wait(.08f);Check(ship.GetComponent<Rigidbody2D>().linearVelocity.x>2&&ship.IsDashing,"Direction can change while boosting");InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return Wait(.2f);ship.enabled=false;body=ship.GetComponent<Rigidbody2D>();body.rotation=0;ship.transform.rotation=Quaternion.identity;body.linearVelocity=Vector2.up*5;yield return Wait(.2f);var outlet=ship.GetComponent<ShipPipeDischarge>();Check(outlet.FlowVisible&&Resources.Load<Sprite>("Voyage/pipe_flow_0").pivot.y>Resources.Load<Sprite>("Voyage/pipe_flow_0").rect.height*.99f,"Supplied animated waste flows from a fixed pipe pivot");ScreenCapture.CaptureScreenshot("Tools/SailingUpdate/pipe-flow.png");yield return Wait(.15f);body.linearVelocity=Vector2.zero;
 yield return P(JourneyStage.SecondUnderwater);yield return Wait(1.2f);yield return P(JourneyStage.ShipBattle);yield return Talk();ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();ship.GetComponent<ShipWeapons>().enabled=false;var producer=UnityEngine.Object.FindFirstObjectByType<EnemySpawner>();var gate=ship.GetComponent<HarborAttackGate>();Check(!producer.enabled&&!gate.HasDeparted&&UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None).Length==0,"Combat waits safely in the harbour");Warp(ship,new Vector2(HarborAttackGate.DepartureX+1,0));yield return Wait(.25f);Check(gate.HasDeparted&&producer.enabled&&UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None).Length>=producer.initialSpawnCount&&producer.initialSpawnCount>=6,"Leaving the harbour starts the larger attacking group");Check(producer.enemiesPerWave>=2&&producer.spawnInterval<4,"Ongoing attack density is increased");var enemy=UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None).First();var prefab=producer.selectedEnemyPrefabs.First(p=>enemy.name.StartsWith(p.name));Check(Vector3.Distance(enemy.transform.localScale,prefab.transform.localScale*1.15f)<.001f,"Attacking fish are proportionally 15% larger");ScreenCapture.CaptureScreenshot("Tools/SailingUpdate/combat.png");yield return Wait(.15f);
 yield return P(JourneyStage.ThirdUnderwater);yield return Wait(1.2f);yield return P(JourneyStage.SharkBattle);yield return Talk();ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();ship.GetComponent<ShipWeapons>().enabled=false;Warp(ship,new Vector2(VoyageHarbor.CoastX+20,18));yield return Wait(.2f);Check(ship.GetComponent<HarborAttackGate>().HasDeparted,"Sailing out north of the pier also starts combat");var view=Camera.main;float initialZoom=view.orthographicSize;yield return P(JourneyStage.Finale);var ending=UnityEngine.Object.FindFirstObjectByType<VoyageEnding>();var dialogue=ship.GetComponent<ShipVisitDialogue>();Check(Time.timeScale==0&&!dialogue.UI.Active&&!ending.FocusComplete,"Finale freezes play before text and begins the flag close-up");var flag=GameObject.Find("White flag • ending only").GetComponent<SpriteRenderer>();var frame=flag.sprite;yield return Wait(.22f);Check(flag.sprite&&flag.sprite!=frame&&flag.bounds.size.magnitude>3,"Large white flag animates while gameplay is frozen");double focus=EditorApplication.timeSinceStartup+5;while(!ending.FocusComplete&&EditorApplication.timeSinceStartup<focus)yield return null;Check(ending.FocusComplete&&view.orthographicSize<initialZoom&&dialogue.UI.Active,"Camera approaches the ship before final dialogue begins");ScreenCapture.CaptureScreenshot("Tools/SailingUpdate/flag-closeup.png");yield return Wait(.2f);double departure=EditorApplication.timeSinceStartup+8;while(!ending.DepartureCovered&&EditorApplication.timeSinceStartup<departure){if(dialogue.UI.Active)dialogue.UI.Advance();yield return null;}var cover=GameObject.Find("Opaque departure cover").GetComponent<Image>();Check(ending.DepartureCovered&&cover.color.a==1&&cover.canvas.renderMode==RenderMode.ScreenSpaceOverlay&&cover.canvas.sortingOrder==10000,"Departure narration has an opaque overlay above ship, guns and flag");ScreenCapture.CaptureScreenshot("Tools/SailingUpdate/departure.png");yield return Wait(.2f);Check(errors==0,"No runtime errors in latest sailing checks");yield return P(JourneyStage.Finale);yield return Wait(.4f);Check(SceneManager.GetActiveScene().name=="MainMenu","P can also skip the finale directly to the menu");
 }
}
